cat >> internal/subscriptions/subscriptions_test.go <<'EOF'

// billedMonthly starts a licensed monthly subscription at start, paid by a card that succeeds.
func billedMonthly(t *testing.T, e *apitest.Env, start time.Time) store.Subscription {
	t.Helper()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_card_visa"; return nil })
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	e.Clock.Set(start)
	sub, err := e.Subs.Create(context.Background(), e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	return sub
}

func TestMonthEndAnchorDoesNotDrift(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	jan31 := time.Date(2026, 1, 31, 10, 0, 0, 0, time.UTC)
	sub := billedMonthly(t, e, jan31)
	if !sub.CurrentPeriodEnd.Equal(time.Date(2026, 2, 28, 10, 0, 0, 0, time.UTC)) {
		t.Fatalf("first period ends %v, want Feb 28", sub.CurrentPeriodEnd)
	}
	for _, want := range []struct{ start, end time.Time }{
		{time.Date(2026, 2, 28, 10, 0, 0, 0, time.UTC), time.Date(2026, 3, 31, 10, 0, 0, 0, time.UTC)},
		{time.Date(2026, 3, 31, 10, 0, 0, 0, time.UTC), time.Date(2026, 4, 30, 10, 0, 0, 0, time.UTC)},
	} {
		e.Clock.Set(want.start)
		if n, err := e.Subs.RenewDue(ctx); err != nil || n != 1 {
			t.Fatalf("RenewDue = %d, %v", n, err)
		}
		got, _ := e.Store.Subscription(e.Acme.ID, sub.ID)
		if !got.CurrentPeriodStart.Equal(want.start) || !got.CurrentPeriodEnd.Equal(want.end) {
			t.Fatalf("period = %v to %v, want %v to %v", got.CurrentPeriodStart, got.CurrentPeriodEnd, want.start, want.end)
		}
	}
}

func TestMissedPeriodsAreRenewedInOrder(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	sub := billedMonthly(t, e, time.Date(2026, 1, 31, 10, 0, 0, 0, time.UTC))
	// The renewal job did not run until April 15: the periods ending Feb 28 and Mar 31 were missed.
	e.Clock.Set(time.Date(2026, 4, 15, 9, 0, 0, 0, time.UTC))
	if n, err := e.Subs.RenewDue(ctx); err != nil || n != 1 {
		t.Fatalf("RenewDue = %d, %v", n, err)
	}
	got, _ := e.Store.Subscription(e.Acme.ID, sub.ID)
	if got.Status != store.Active || !got.CurrentPeriodStart.Equal(time.Date(2026, 3, 31, 10, 0, 0, 0, time.UTC)) ||
		!got.CurrentPeriodEnd.Equal(time.Date(2026, 4, 30, 10, 0, 0, 0, time.UTC)) {
		t.Fatalf("after the missed periods = %+v", got)
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 3 {
		t.Fatalf("invoices = %d, want one per period", len(invs))
	}
	for i, want := range []struct{ start, end time.Time }{
		{time.Date(2026, 1, 31, 10, 0, 0, 0, time.UTC), time.Date(2026, 2, 28, 10, 0, 0, 0, time.UTC)},
		{time.Date(2026, 2, 28, 10, 0, 0, 0, time.UTC), time.Date(2026, 3, 31, 10, 0, 0, 0, time.UTC)},
		{time.Date(2026, 3, 31, 10, 0, 0, 0, time.UTC), time.Date(2026, 4, 30, 10, 0, 0, 0, time.UTC)},
	} {
		inv := invs[i]
		if inv.PeriodStart == nil || inv.PeriodEnd == nil || !inv.PeriodStart.Equal(want.start) || !inv.PeriodEnd.Equal(want.end) || inv.Status != store.InvoicePaid {
			t.Errorf("invoice %d = %+v, want paid for %v to %v", i, inv, want.start, want.end)
		}
	}
	if cs := e.Gateway.Charges(); len(cs) != 3 {
		t.Fatalf("charges = %d, want 3", len(cs))
	}
}

func TestTrialAnchorsThePeriods(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_card_visa"; return nil })
	p, err := e.Store.CreatePlan(store.Plan{OrgID: e.Acme.ID, Name: "Pro", Currency: money.USD, UnitAmount: 4900, Interval: store.Monthly, TrialDays: 30}, e.Clock.Now())
	if err != nil {
		t.Fatal(err)
	}
	e.Clock.Set(time.Date(2026, 1, 1, 10, 0, 0, 0, time.UTC))
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	trialEnd := time.Date(2026, 1, 31, 10, 0, 0, 0, time.UTC)
	if sub.TrialEnd == nil || !sub.TrialEnd.Equal(trialEnd) {
		t.Fatalf("trial end = %v, want %v", sub.TrialEnd, trialEnd)
	}
	// The job runs on March 2: the first paid period (Jan 31 to Feb 28) and the one after it (Feb 28 to Mar 31) are renewed.
	e.Clock.Set(time.Date(2026, 3, 2, 9, 0, 0, 0, time.UTC))
	if _, err := e.Subs.RenewDue(ctx); err != nil {
		t.Fatal(err)
	}
	got, _ := e.Store.Subscription(e.Acme.ID, sub.ID)
	if !got.CurrentPeriodStart.Equal(time.Date(2026, 2, 28, 10, 0, 0, 0, time.UTC)) || !got.CurrentPeriodEnd.Equal(time.Date(2026, 3, 31, 10, 0, 0, 0, time.UTC)) {
		t.Fatalf("period = %v to %v", got.CurrentPeriodStart, got.CurrentPeriodEnd)
	}
	if invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID}); len(invs) != 2 || !invs[0].PeriodStart.Equal(trialEnd) {
		t.Fatalf("invoices = %+v, want the two paid periods", invs)
	}
}

func TestMeteredMissedPeriodsBillTheirOwnUsage(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_card_visa"; return nil })
	p, _ := e.Store.CreatePlan(store.Plan{OrgID: e.Acme.ID, Name: "API calls", Currency: money.USD, UnitAmount: 2, Interval: store.Monthly, UsageType: store.Metered}, e.Clock.Now())
	e.Clock.Set(time.Date(2026, 1, 31, 10, 0, 0, 0, time.UTC))
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	for _, u := range []struct {
		q  int64
		at time.Time
	}{{100, time.Date(2026, 2, 10, 0, 0, 0, 0, time.UTC)}, {250, time.Date(2026, 3, 10, 0, 0, 0, 0, time.UTC)}} {
		if _, err := e.Store.AddUsage(e.Acme.ID, sub.ID, u.q, u.at, e.Clock.Now()); err != nil {
			t.Fatal(err)
		}
	}
	e.Clock.Set(time.Date(2026, 4, 15, 9, 0, 0, 0, time.UTC))
	if _, err := e.Subs.RenewDue(ctx); err != nil {
		t.Fatal(err)
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 2 || invs[0].Lines[0].Quantity != 100 || invs[1].Lines[0].Quantity != 250 ||
		!invs[1].PeriodStart.Equal(time.Date(2026, 2, 28, 10, 0, 0, 0, time.UTC)) || !invs[1].PeriodEnd.Equal(time.Date(2026, 3, 31, 10, 0, 0, 0, time.UTC)) {
		t.Fatalf("invoices = %+v, want usage of each missed period", invs)
	}
}
