162	func (s *Service) renew(ctx context.Context, sub store.Subscription, now time.Time) error {
163		plan, ok := s.Store.Plan(sub.OrgID, sub.PlanID)
164		if !ok {
165			return store.ErrNotFound
166		}
167		if sub.CancelAtPeriodEnd {
168			end := sub.CurrentPeriodEnd
169			sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
170				x.Status, x.CanceledAt = store.Canceled, &end
171				return nil
172			})
173			if err == nil {
174				s.publish(ctx, sub.OrgID, "subscription.canceled", sub)
175			}
176			return err
177		}
178		// Each missed period is renewed in order, from the one that starts where the current period ends, so the boundaries
179		// fall on the anchor's schedule whatever time the job runs.
180		anchor := billing.Anchor(sub.StartedAt, sub.TrialEnd)
181		n := 0
182		for billing.PeriodStart(anchor, plan.Interval, n).Before(sub.CurrentPeriodEnd) {
183			n++
184		}
185		pastDue := false
186		for !sub.CurrentPeriodEnd.After(now) {
187			start := billing.PeriodStart(anchor, plan.Interval, n)
188			end := billing.PeriodStart(anchor, plan.Interval, n+1)
189			paid := true
190			var err error
191			switch {
192			case plan.UsageType == store.Metered && sub.Status != store.Trialing:
193				paid, err = s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
194			case plan.UsageType == store.Licensed:
195				paid, err = s.invoicePeriod(ctx, sub, plan, start, end)
196			}
197			if err != nil {
198				return err
199			}
200			pastDue = pastDue || !paid
201			status := store.Active
202			if pastDue {
203				status = store.PastDue
204			}
205			sub, err = s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
206				x.CurrentPeriodStart, x.CurrentPeriodEnd = start, end
207				x.Status = status
208				return nil
209			})
210			if err != nil {
211				return err
212			}
213			s.publish(ctx, sub.OrgID, "subscription.updated", sub)
214			n++
215		}
216		return nil
217	}
