220	// It reports false when the charge was declined. An invoice that needs no charge is marked paid; one whose customer has no
221	// payment method stays open and counts as paid here (it is paid by hand).
222	func (s *Service) invoicePeriod(ctx context.Context, sub store.Subscription, plan store.Plan, start, end time.Time) (bool, error) {
223		var lines []store.Line
224		period := start.Format("Jan 2, 2006") + " to " + end.Format("Jan 2, 2006")
225		switch plan.UsageType {
226		case store.Licensed:
227			if plan.UnitAmount > 0 {
228				lines = append(lines, store.Line{Description: plan.Name + ", " + period, Quantity: int64(sub.Quantity), UnitAmount: plan.UnitAmount})
229			}
230		case store.Metered:
231			if used := s.Store.UsageTotal(sub.OrgID, sub.ID, start, end); used > 0 {
232				lines = append(lines, store.Line{Description: plan.Name + " usage, " + period, Quantity: used, UnitAmount: plan.UnitAmount})
233			}
234		}
235		ps, pe := start, end
236		inv, err := s.Store.CreateInvoice(store.Invoice{OrgID: sub.OrgID, CustomerID: sub.CustomerID, SubscriptionID: sub.ID, Currency: plan.Currency,
237			Lines: lines, DiscountPercent: sub.DiscountPercent, PeriodStart: &ps, PeriodEnd: &pe}, s.Clock.Now())
238		if err != nil {
239			return false, err
240		}
241		s.publish(ctx, sub.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID, "subscription_id": sub.ID})
242		_, _, err = s.Payments.Pay(ctx, sub.OrgID, inv.ID, "")
243		var decline *payments.DeclineError
244		switch {
245		case err == nil, errors.Is(err, payments.ErrNoPaymentMethod):
246			return true, nil
247		case errors.As(err, &decline):
248			return false, nil
249		default:
250			return false, err
251		}
252	}
