254	func (s *Service) setStatus(ctx context.Context, sub store.Subscription, st store.SubStatus) (store.Subscription, error) {
255		sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
256			x.Status = st
257			return nil
258		})
259		if err == nil {
260			s.publish(ctx, sub.OrgID, "subscription.updated", sub)
261		}
262		return sub, err
263	}
