200			if inv.PeriodStart == nil || inv.PeriodEnd == nil || !inv.PeriodStart.Equal(want.start) || !inv.PeriodEnd.Equal(want.end) || inv.Status != store.InvoicePaid {
201				t.Errorf("invoice %d = %+v, want paid for %v to %v", i, inv, want.start, want.end)
202			}
203		}
204		if cs := e.Gateway.Charges(); len(cs) != 3 {
205			t.Fatalf("charges = %d, want 3", len(cs))
206		}
207	}
