package billing

import (
	"testing"
	"time"

	"example.com/tally/internal/store"
)

func TestCompute(t *testing.T) {
	inv := store.Invoice{
		Lines:           []store.Line{{Description: "Seats", Quantity: 3, UnitAmount: 1500}, {Description: "Setup", Quantity: 1, UnitAmount: 999}},
		DiscountPercent: 10,
		TaxRateBP:       825,
	}
	got := Compute(inv)
	// subtotal 5499; discount 549.9 -> 550; taxable 4949; tax 408.2925 -> 408
	want := Totals{Subtotal: 5499, Discount: 550, Tax: 408, Total: 5357}
	if got != want {
		t.Fatalf("Compute = %+v, want %+v", got, want)
	}
}

func TestComputeWithoutDiscountOrTax(t *testing.T) {
	got := Compute(store.Invoice{Lines: []store.Line{{Description: "x", Quantity: 2, UnitAmount: 250}}})
	if got != (Totals{Subtotal: 500, Total: 500}) {
		t.Fatalf("Compute = %+v", got)
	}
}

func TestAddInterval(t *testing.T) {
	start := time.Date(2026, 3, 14, 9, 30, 0, 0, time.UTC)
	if got := AddInterval(start, store.Monthly); !got.Equal(time.Date(2026, 4, 14, 9, 30, 0, 0, time.UTC)) {
		t.Errorf("monthly: %v", got)
	}
	if got := AddInterval(start, store.Yearly); !got.Equal(time.Date(2027, 3, 14, 9, 30, 0, 0, time.UTC)) {
		t.Errorf("yearly: %v", got)
	}
	jan31 := time.Date(2026, 1, 31, 0, 0, 0, 0, time.UTC)
	if got := AddInterval(jan31, store.Monthly); !got.Equal(time.Date(2026, 2, 28, 0, 0, 0, 0, time.UTC)) {
		t.Errorf("month end: %v", got)
	}
}

func TestPeriodStartKeepsTheAnchorsDay(t *testing.T) {
	anchor := time.Date(2026, 1, 31, 15, 4, 5, 0, time.UTC)
	for n, w := range map[int]time.Time{
		0:  time.Date(2026, 1, 31, 15, 4, 5, 0, time.UTC),
		1:  time.Date(2026, 2, 28, 15, 4, 5, 0, time.UTC),
		2:  time.Date(2026, 3, 31, 15, 4, 5, 0, time.UTC),
		3:  time.Date(2026, 4, 30, 15, 4, 5, 0, time.UTC),
		4:  time.Date(2026, 5, 31, 15, 4, 5, 0, time.UTC),
		12: time.Date(2027, 1, 31, 15, 4, 5, 0, time.UTC),
	} {
		if got := PeriodStart(anchor, store.Monthly, n); !got.Equal(w) {
			t.Errorf("monthly n=%d: %v, want %v", n, got, w)
		}
	}
}

func TestPeriodStartYearlyFromLeapDay(t *testing.T) {
	anchor := time.Date(2028, 2, 29, 0, 0, 0, 0, time.UTC)
	for n, w := range map[int]time.Time{
		1: time.Date(2029, 2, 28, 0, 0, 0, 0, time.UTC),
		2: time.Date(2030, 2, 28, 0, 0, 0, 0, time.UTC),
		3: time.Date(2031, 2, 28, 0, 0, 0, 0, time.UTC),
		4: time.Date(2032, 2, 29, 0, 0, 0, 0, time.UTC),
	} {
		if got := PeriodStart(anchor, store.Yearly, n); !got.Equal(w) {
			t.Errorf("yearly n=%d: %v, want %v", n, got, w)
		}
	}
	if got := PeriodStart(anchor, store.Monthly, 12); !got.Equal(time.Date(2029, 2, 28, 0, 0, 0, 0, time.UTC)) {
		t.Errorf("monthly from Feb 29: %v", got)
	}
	if got := PeriodStart(anchor, store.Monthly, 1); !got.Equal(time.Date(2028, 3, 29, 0, 0, 0, 0, time.UTC)) {
		t.Errorf("monthly from Feb 29, n=1: %v", got)
	}
}

