func TestNextPeriodStart(t *testing.T) {
	anchor := time.Date(2026, 1, 31, 15, 4, 5, 0, time.UTC)
	for _, c := range []struct {
		name string
		iv   store.Interval
		t    time.Time
		want time.Time
	}{
		{"on the schedule", store.Monthly, anchor, time.Date(2026, 2, 28, 15, 4, 5, 0, time.UTC)},
		{"before the anchor", store.Monthly, time.Date(2025, 12, 1, 0, 0, 0, 0, time.UTC), anchor},
		{"between boundaries", store.Monthly, time.Date(2026, 3, 3, 0, 0, 0, 0, time.UTC), time.Date(2026, 3, 31, 15, 4, 5, 0, time.UTC)},
		{"monthly, a year on", store.Monthly, time.Date(2027, 1, 31, 15, 4, 5, 0, time.UTC), time.Date(2027, 2, 28, 15, 4, 5, 0, time.UTC)},
		{"yearly, off the schedule", store.Yearly, time.Date(2026, 2, 28, 10, 0, 0, 0, time.UTC), time.Date(2027, 1, 31, 15, 4, 5, 0, time.UTC)},
		{"yearly, on the schedule", store.Yearly, time.Date(2027, 1, 31, 15, 4, 5, 0, time.UTC), time.Date(2028, 1, 31, 15, 4, 5, 0, time.UTC)},
	} {
		if got := NextPeriodStart(anchor, c.iv, c.t); !got.Equal(c.want) {
			t.Errorf("%s: NextPeriodStart(%v) = %v, want %v", c.name, c.t, got, c.want)
		}
	}
}

