// requireInvoicedPeriods checks that the subscription has one paid invoice per period in want, in order.
func requireInvoicedPeriods(t *testing.T, e *apitest.Env, subID string, want [][2]time.Time) {
	t.Helper()
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: subID})
	if len(invs) != len(want) {
		t.Fatalf("invoices = %d, want %d: %+v", len(invs), len(want), invs)
	}
	for i, w := range want {
		inv := invs[i]
		if inv.PeriodStart == nil || inv.PeriodEnd == nil || !inv.PeriodStart.Equal(w[0]) || !inv.PeriodEnd.Equal(w[1]) || inv.Status != store.InvoicePaid {
			t.Errorf("invoice %d = %+v, want paid for %v to %v", i, inv, w[0], w[1])
		}
	}
}

