144	// RenewDue renews every subscription, of every organization, whose current period has ended. A subscription set to cancel
145	// at the end of its period is canceled. Otherwise its next period starts and is invoiced: a licensed plan bills the new
146	// period in advance, a metered plan bills the usage of the period that ended. A declined charge makes the subscription past
147	// due. RenewDue returns how many subscriptions it renewed or canceled.
148	func (s *Service) RenewDue(ctx context.Context) (int, error) {
149		now := s.Clock.Now()
150		n := 0
151		for _, sub := range s.Store.DueSubscriptions(now) {
152			if err := ctx.Err(); err != nil {
153				return n, err
154			}
155			if err := s.renew(ctx, sub, now); err != nil {
156				return n, fmt.Errorf("renew %s: %w", sub.ID, err)
157			}
158			n++
159		}
160		return n, nil
161	}
