163	func (s *Service) renew(ctx context.Context, sub store.Subscription, now time.Time) error {
164		plan, ok := s.Store.Plan(sub.OrgID, sub.PlanID)
165		if !ok {
166			return store.ErrNotFound
167		}
168		if sub.CancelAtPeriodEnd {
169			end := sub.CurrentPeriodEnd
170			sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
171				x.Status, x.CanceledAt = store.Canceled, &end
172				return nil
173			})
174			if err == nil {
175				s.publish(ctx, sub.OrgID, "subscription.canceled", sub)
176			}
177			return err
178		}
179		// Each missed period is renewed in order. A period starts where the previous one ended and ends at the next boundary of
180		// the anchor's schedule, so the boundaries do not depend on when the job runs. The stored end is normally on the schedule
181		// already. It is not after a change of interval (a monthly period ending Feb 28 under a yearly plan anchored Jan 31), nor
182		// when an earlier renewal drifted it off the schedule; the period from it then runs to the next boundary, and the schedule
183		// resumes there.
184		anchor := billing.Anchor(sub.StartedAt, sub.TrialEnd)
185		pastDue := false
186		for !sub.CurrentPeriodEnd.After(now) {
187			start := sub.CurrentPeriodEnd
188			end := billing.NextPeriodStart(anchor, plan.Interval, start)
189			paid := true
190			var err error
191			switch {
192			case plan.UsageType == store.Metered && sub.Status != store.Trialing:
193				paid, err = s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
194			case plan.UsageType == store.Licensed:
195				paid, err = s.invoicePeriod(ctx, sub, plan, start, end)
196			}
197			if err != nil {
198				return err
199			}
200			pastDue = pastDue || !paid
201			status := store.Active
202			if pastDue {
203				status = store.PastDue
204			}
205			sub, err = s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
206				x.CurrentPeriodStart, x.CurrentPeriodEnd = start, end
207				x.Status = status
208				return nil
209			})
210			if err != nil {
211				return err
212			}
213			s.publish(ctx, sub.OrgID, "subscription.updated", sub)
214		}
215		return nil
216	}
